16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
23	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
25	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
26	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
27	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
28	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
29	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
30	    @Mapping(target = "locality", expression = "java(locality(owner))")
31	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
32	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
33	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
34	    @Mapping(target = "bulkSignupWarning", ignore = true)
35	    @Mapping(target = "identityKey", ignore = true)
36	    @Mapping(target = "possibleDuplicate", ignore = true)
37	    @Mapping(target = "possibleDuplicateOf", ignore = true)
38	    OwnerDto toOwnerDto(Owner owner);
39	
40	    /**
41	     * Derives the owner's {@code salutation} from its optional {@code title} and its {@code lastName}:
42	     * the title, a single space and the last name when a title is present (e.g. {@code 'DR Franklin'}),
43	     * otherwise just the last name. A {@code null} or blank title yields the bare last name.
44	     *
45	     * @param owner the owner being mapped
46	     * @return the derived salutation
47	     */
48	    default String salutation(Owner owner) {
49	        String title = owner.getTitle();
50	        if (title == null || title.isBlank()) {
51	            return owner.getLastName();
52	        }
53	        return title + " " + owner.getLastName();
54	    }
55	
56	    /**
57	     * Derives the owner's {@code contactPreference} from the owner's own fields:
58	     * {@code EMAIL} when an email is present, otherwise {@code PHONE}.
59	     *
60	     * @param owner the owner being mapped
61	     * @return the derived contact preference
62	     */
63	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
64	        return hasEmail(owner) ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
65	    }
66	
67	    /**
68	     * Reports whether the owner has a usable {@code email}: present and not blank (whitespace-only).
69	     * The presence of an email drives several derived fields (such as the {@code contactPreference}
70	     * and the {@code membershipLevel}), so the "has an email" test is written in exactly one place
71	     * rather than repeated at each use.
72	     *
73	     * @param owner the owner being mapped
74	     * @return {@code true} when the owner has a non-blank email
75	     */
76	    default boolean hasEmail(Owner owner) {
77	        return owner.getEmail() != null && !owner.getEmail().isBlank();
78	    }
79	
80	    /**
81	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against the owner's
82	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} for 18 to 64, and
83	     * {@code SENIOR} for 65 and over. Returns {@code null} when no birth date is present, in which
84	     * case the field is absent from the response. The age in whole years is the number of complete
85	     * years between the birth date and the registration date (see {@link java.time.Period}); when the
86	     * registration date is somehow absent the current date is used as the reference.
87	     *
88	     * @param owner the owner being mapped
89	     * @return the derived age band, or {@code null} when no birth date is present
90	     */
91	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
92	        java.time.LocalDate birthDate = owner.getBirthDate();
93	        if (birthDate == null) {
94	            return null;
95	        }
96	        java.time.LocalDate reference = owner.getRegistrationDate() != null
97	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
98	        int age = java.time.Period.between(birthDate, reference).getYears();
99	        if (age < 18) {
100	            return OwnerDto.AgeBandEnum.MINOR;
101	        }
102	        if (age < 65) {
103	            return OwnerDto.AgeBandEnum.ADULT;
104	        }
105	        return OwnerDto.AgeBandEnum.SENIOR;
106	    }
107	
108	    /**
109	     * Derives the owner's {@code locality} as the {@code REGION} segment of its {@code customerCode}
110	     * (the part before the {@code '-'}), which is the owner's canonical region code baked into the
111	     * region-and-hash identity {@code '<REGION>-<HASH8>'}. When no customer code is present (e.g. seed
112	     * data) it falls back to resolving the region directly from the owner's {@code postcode} and
113	     * {@code city} through the shared {@link Region#code(String, String)}. Reading the region from the
114	     * identity keeps the locality consistent with the code an owner is issued.
115	     *
116	     * @param owner the owner being mapped
117	     * @return the derived locality
118	     */
119	    default String locality(Owner owner) {
120	        String code = owner.getCustomerCode();
121	        if (code == null) {
122	            return Region.code(owner.getPostcode(), owner.getCity());
123	        }
124	        int dash = code.indexOf('-');
125	        return dash >= 0 ? code.substring(0, dash) : code;
126	    }
127	
128	    /**
129	     * Derives the owner's {@code timezone} as the IANA name for its {@link #locality(Owner) locality}
130	     * region, resolved through the shared fixed region-to-timezone table
131	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
132	     * {@code QLD -> Australia/Brisbane}) in {@link Region#timezoneForCode(String)}. Deriving it from
133	     * the same locality keeps the timezone consistent with the region the owner is labelled with.
134	     * Returns {@code null} when the locality has no known timezone (such as an {@code UNKNOWN}
135	     * region), in which case the field is absent from the response.
136	     *
137	     * @param owner the owner being mapped
138	     * @return the derived IANA timezone name, or {@code null} when the region has no known timezone
139	     */
140	    default String timezone(Owner owner) {
141	        return Region.timezoneForCode(locality(owner));
142	    }
143	
144	    /**
145	     * Derives the owner's {@code membershipPoints} from the owner's factors. Starts at {@code 0},
146	     * adds {@code 2} when an email is present, adds {@code 1} when the owner's {@code namesakeCount}
147	     * is {@code 0}, adds {@code 2} for a household of {@code 3} or more (see
148	     * {@link Owner#getHouseholdSize()}), and adds {@code 3} when the owner's tenure &mdash; the number
149	     * of whole days between its {@code registrationDate} and the current date &mdash; exceeds
150	     * {@code 365}.
151	     *
152	     * @param owner the owner being mapped
153	     * @return the derived membership points
154	     */
155	    default Integer membershipPoints(Owner owner) {
156	        int points = 0;
157	        if (hasEmail(owner)) {
158	            points += 2;
159	        }
160	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
161	        if (uniqueName) {
162	            points += 1;
163	        }
164	        if (owner.getHouseholdSize() >= 3) {
165	            points += 2;
166	        }
167	        if (tenureDays(owner) > 365) {
168	            points += 3;
169	        }
170	        return points;
171	    }
172	
173	    /**
174	     * Maps the owner's {@code membershipPoints} to its numeric {@code membershipLevel}: level
175	     * {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
176	     * {@code 4} for {@code 6} or more points.
177	     *
178	     * @param owner the owner being mapped
179	     * @return the derived membership level, between {@code 1} and {@code 4}
180	     */
181	    default Integer membershipLevel(Owner owner) {
182	        int points = membershipPoints(owner);
183	        if (points <= 1) {
184	            return 1;
185	        }
186	        if (points <= 3) {
187	            return 2;
188	        }
189	        if (points <= 5) {
190	            return 3;
191	        }
192	        return 4;
193	    }
194	
195	    /**
196	     * Computes the owner's tenure in whole days: the number of complete days between the owner's
197	     * {@code registrationDate} and the current date. Returns {@code 0} when no registration date is
198	     * present, so an owner without a registration date has no tenure.
199	     *
200	     * @param owner the owner being mapped
201	     * @return the owner's tenure in whole days, or {@code 0} when no registration date is present
202	     */
203	    default long tenureDays(Owner owner) {
204	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
205	        if (registrationDate == null) {
206	            return 0;
207	        }
208	        return java.time.temporal.ChronoUnit.DAYS.between(registrationDate, java.time.LocalDate.now());
209	    }
210	
211	    /**
212	     * Builds the owner's {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'},
213	     * where {@code YY} is the last two digits of the {@code registrationDate} year (e.g.
214	     * {@code 'NSW-1A2B3C4D-M26'}). Returns {@code null} when either the customer code or the
215	     * registration date is absent.
216	     *
217	     * @param owner the owner being mapped
218	     * @return the formatted membership number, or {@code null} when it cannot be derived
219	     */
220	    default String membershipNumber(Owner owner) {
221	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
222	            return null;
223	        }
224	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
225	    }
226	
227	    /**
228	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
229	     * contained in the {@code customerCode} (non-digit characters, such as the {@code '<REGION>-'}
230	     * prefix, the separator and the hex letters {@code A-F}, are ignored). Returns {@code null} when
231	     * the customer code is absent.
232	     *
233	     * @param owner the owner being mapped
234	     * @return the Luhn check digit, or {@code null} when no customer code is present
235	     */
236	    default Integer checkDigit(Owner owner) {
237	        String code = owner.getCustomerCode();
238	        if (code == null) {
239	            return null;
240	        }
241	        int sum = 0;
242	        boolean dbl = true;
243	        for (int i = code.length() - 1; i >= 0; i--) {
244	            char c = code.charAt(i);
245	            if (c < '0' || c > '9') {
246	                continue;
247	            }
248	            int d = c - '0';
249	            if (dbl) {
250	                d *= 2;
251	                if (d > 9) {
252	                    d -= 9;
253	                }
254	            }
255	            sum += d;
256	            dbl = !dbl;
257	        }
258	        return (10 - (sum % 10)) % 10;
259	    }
260	
261	    /**
262	     * Formats the owner's stored E.164 {@code telephone} for human display: the country calling
263	     * code, a space, then the national-significant digits grouped in threes separated by spaces
264	     * (e.g. {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw {@code telephone}
265	     * field keeps the unformatted E.164 value. The split between the country code and the national
266	     * digits mirrors the recognised calling codes of the {@code TelephoneNormalizer}: Australian
267	     * {@code +61} (9 national digits) and North American {@code +1} (10); an unrecognised or
268	     * malformed value falls back to a single leading digit. Returns the value unchanged when it is
269	     * {@code null}, blank, or not in E.164 form.
270	     *
271	     * @param owner the owner being mapped
272	     * @return the human-formatted telephone, or the raw value when it cannot be formatted
273	     */
274	    default String telephoneDisplay(Owner owner) {
275	        String telephone = owner.getTelephone();
276	        if (telephone == null || telephone.isBlank() || !telephone.startsWith("+")) {
277	            return telephone;
278	        }
279	        String digits = telephone.substring(1);
280	        int codeLength = (digits.startsWith("61") && digits.length() == 2 + 9) ? 2 : 1;
281	        String countryCode = digits.substring(0, codeLength);
282	        String national = digits.substring(codeLength);
283	        StringBuilder grouped = new StringBuilder();
284	        for (int i = 0; i < national.length(); i++) {
285	            if (i > 0 && i % 3 == 0) {
286	                grouped.append(' ');
287	            }
288	            grouped.append(national.charAt(i));
289	        }
290	        return "+" + countryCode + " " + grouped;
291	    }
292	
293	    Owner toOwner(OwnerDto ownerDto);
294	
295	    @Mapping(target = "id", ignore = true)
296	    @Mapping(target = "pets", ignore = true)
297	    Owner toOwner(OwnerFieldsDto ownerDto);
298	
299	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
300	
301	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
302	
303	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
304	        OwnerPageDto ownerPageDto = new OwnerPageDto();
305	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
306	        ownerPageDto.setPage(ownerPage.getNumber());
307	        ownerPageDto.setSize(ownerPage.getSize());
308	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
309	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
310	        return ownerPageDto;
311	    }
312	}
